script.setup:
// cannon-es simulates the rigid bodies: a brick wall and a heavy ball fired at
// it every few seconds. Each body's position and quaternion become a model matrix.
const mod = await ctx.utils.import("https://esm.sh/cannon-es@0.20.0");
const C = mod.default ?? mod;
const world = new C.World({ gravity: new C.Vec3(0, -9.82, 0) });
world.broadphase = new C.SAPBroadphase(world);
world.allowSleep = true;
world.solver.iterations = 20;
world.defaultContactMaterial.friction = 0.4;
world.defaultContactMaterial.restitution = 0.1;
const floor = new C.Body({ mass: 0, shape: new C.Plane() });
floor.quaternion.setFromEuler(-Math.PI / 2, 0, 0);
world.addBody(floor);
const bricks = [], balls = [];
const build = () => {
  for (const b of [...bricks, ...balls]) world.removeBody(b);
  bricks.length = balls.length = 0;
  const W = 9, H = 9, bw = 0.8, bh = 0.4, bd = 0.4;
  for (let row = 0; row < H; row++) for (let i = 0; i < W - (row % 2); i++) {
    const body = new C.Body({ mass: 1, shape: new C.Box(new C.Vec3(bw / 2 - 0.005, bh / 2 - 0.005, bd / 2 - 0.005)) });
    body.position.set((i - (W - 1) / 2 + (row % 2) * 0.5) * bw, bh / 2 + row * bh, 0);
    body.allowSleep = true; body.sleepSpeedLimit = 0.15;
    body.size = [bw, bh, bd]; body.tint = (row * 7 + i * 3) % 5;
    world.addBody(body); bricks.push(body);
    // Start asleep so the wall stands still until something hits it.
    body.sleep();
  }
};
build();
const box = ctx.utils.createMesh(ctx.utils.geometry.box()), sphere = ctx.utils.createMesh(ctx.utils.geometry.sphere(32));
const prog = ctx.utils.createProgram(`#version 300 es
layout(location=0) in vec3 a_position; layout(location=1) in vec3 a_normal;
uniform mat4 u_vp, u_model; out vec3 v_n; out vec3 v_w;
void main() { vec4 w = u_model * vec4(a_position, 1.0); v_w = w.xyz; v_n = mat3(u_model) * a_normal; gl_Position = u_vp * w; }`, `#version 300 es
precision highp float; in vec3 v_n; in vec3 v_w; out vec4 outColor;
uniform vec3 u_color, u_eye; uniform float u_floor;
void main() {
  vec3 n = normalize(v_n), v = normalize(u_eye - v_w), l = normalize(vec3(0.5, 0.9, 0.35));
  vec3 base = u_color;
  if (u_floor > 0.5) {
    // A soft grid that fades into the background.
    vec2 g = abs(fract(v_w.xz) - 0.5);
    float line = smoothstep(0.47, 0.5, max(g.x, g.y));
    base = mix(vec3(0.13, 0.14, 0.18), vec3(0.22, 0.24, 0.3), line) * exp(-length(v_w.xz) * 0.06);
  }
  float d = max(dot(n, l), 0.0), sp = pow(max(dot(n, normalize(l + v)), 0.0), 40.0) * (1.0 - u_floor);
  vec3 c = base * (0.18 + 0.82 * d) + base * vec3(0.3, 0.4, 0.7) * max(-n.x, 0.0) * 0.4 + sp * 0.35;
  outColor = vec4(pow(c, vec3(0.4545)), 1.0);
}`);
Object.assign(ctx.state, { C, world, bricks, balls, build, box, sphere, prog, clock: 0, shots: 0, m: new Float32Array(16),
  camera: ctx.utils.createOrbitCamera({ distance: 14, theta: 1.0, phi: 1.2, target: [0, 1.5, 0] }) });

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, { mat4 } = ctx.utils, [w, h] = ctx.resolution, { C } = s;
s.clock += ctx.dt;
// Fire a ball every few seconds; rebuild the wall after three shots.
if (u.u_reset || s.clock > 4.5 * 3 + 2.5) { s.build(); s.clock = 0; s.shots = 0; }
if (s.shots < 3 && s.clock > 1 + s.shots * 4.5) {
  const side = s.shots % 2 ? -1 : 1, r = 0.45;
  const ball = new C.Body({ mass: u.u_mass, shape: new C.Sphere(r) });
  ball.position.set(side * 2.5 * Math.random(), 1 + s.shots * 0.9, 9);
  ball.velocity.set(-side * 0.6, 3.5, -u.u_power);
  ball.r = r;
  s.world.addBody(ball); s.balls.push(ball); s.shots++;
}
s.world.fixedStep(1 / 60, ctx.dt);
s.camera.update(ctx.mouse, ctx.mousePrev, ctx.mouseDown, ctx.keys, ctx.dt);
const vp = mat4.multiply(s.camera.getProjectionMatrix(w / h, 40, 0.1, 100), s.camera.getViewMatrix());
gl.enable(gl.DEPTH_TEST);
gl.clearColor(0.03, 0.033, 0.045, 1);
gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
gl.useProgram(s.prog);
ctx.utils.setUniforms(s.prog, { u_vp: vp, u_eye: s.camera.getEye(), u_floor: 1, u_color: [0, 0, 0], u_model: mat4.multiply(mat4.fromTranslation(0, -0.05, 0), mat4.fromScaling(60, 0.1, 60)) });
s.box.draw();
gl.uniform1f(gl.getUniformLocation(s.prog, "u_floor"), 0);
// Model matrix from the body's quaternion, position and size.
const model = (b, sx, sy, sz) => {
  const { x, y, z, w: qw } = b.quaternion, m = s.m;
  const x2 = x + x, y2 = y + y, z2 = z + z;
  m[0] = (1 - y * y2 - z * z2) * sx; m[1] = (x * y2 + qw * z2) * sx; m[2] = (x * z2 - qw * y2) * sx; m[3] = 0;
  m[4] = (x * y2 - qw * z2) * sy; m[5] = (1 - x * x2 - z * z2) * sy; m[6] = (y * z2 + qw * x2) * sy; m[7] = 0;
  m[8] = (x * z2 + qw * y2) * sz; m[9] = (y * z2 - qw * x2) * sz; m[10] = (1 - x * x2 - y * y2) * sz; m[11] = 0;
  m[12] = b.position.x; m[13] = b.position.y; m[14] = b.position.z; m[15] = 1;
  return m;
};
const tints = [u.u_brickA, u.u_brickB, u.u_brickA.map((c, i) => (c + u.u_brickB[i]) / 2), u.u_brickA.map((c) => c * 0.8), u.u_brickB.map((c) => c * 0.85)];
for (const b of s.bricks) {
  ctx.utils.setUniforms(s.prog, { u_model: model(b, ...b.size), u_color: tints[b.tint] });
  s.box.draw();
}
for (const b of s.balls) {
  ctx.utils.setUniforms(s.prog, { u_model: model(b, b.r * 2, b.r * 2, b.r * 2), u_color: [0.9, 0.9, 0.95] });
  s.sphere.draw();
}
ctx.publish("bodies", s.world.bodies.length);
ctx.publish("awake", s.world.bodies.filter((b) => b.mass > 0 && b.sleepState === 0).length);
